<?php namespace App\Domains\Order\Enums; enum OrderStatus: string { case Pending = 'pending'; case Paid = 'paid'; case Processing = 'processing'; case Shipped = 'shipped'; case Delivered = 'delivered'; case Cancelled = 'cancelled'; case Refunded = 'refunded'; case Expired = 'expired'; public function allowedTransitions(): array { return match($this) { self::Pending => [self::Paid, self::Cancelled, self::Expired], self::Paid => [self::Processing, self::Cancelled, self::Refunded], self::Processing => [self::Shipped], self::Shipped => [self::Delivered], default => [], }; } public function label(): string { return match($this) { self::Pending => 'Pendiente', self::Paid => 'Pagado', self::Processing => 'En proceso', self::Shipped => 'Enviado', self::Delivered => 'Entregado', self::Cancelled => 'Cancelado', self::Refunded => 'Reembolsado', self::Expired => 'Expirado', }; } }